// One shape for every booking, whichever door it came through.
// Cal door: the Cal.com BOOKING_CREATED webhook. Manual door: a JSON body already in this shape
// (email, firstName, lastName, domain, startTime, title, meetingUrl, notes, source, hostKeys[], clientRecId).
const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
const FREEMAIL=new Set(['gmail.com','googlemail.com','yahoo.com','hotmail.com','outlook.com','live.com','icloud.com','me.com','aol.com','protonmail.com','proton.me','gmx.com','mail.com','walla.co.il','walla.com']);
const stripDomain=(u)=>String(u||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0].split('?')[0];
let cal=null, manual=null;
try{ cal=$('Cal Booking').first().json; }catch(e){}
try{ manual=$('Manual Booking').first().json; }catch(e){}
let out;
if(cal){
  const b=cal.body||{}; const p=b.payload||{};
  if(String(b.triggerEvent||'')!=='BOOKING_CREATED'){ return [{ json:{ _ignore:true, reason:'Cal.com event '+(b.triggerEvent||'?')+' is not a booking' } }]; }
  const a=(p.attendees||[])[0]||{};
  const email=String(a.email||'').toLowerCase().trim();
  const nameParts=String(a.name||'').trim().split(/\s+/);
  const website=(p.responses&&p.responses.website&&p.responses.website.value)||'';
  const emailDomain=email.split('@')[1]||'';
  const domain=stripDomain(website)||(FREEMAIL.has(emailDomain)?'':emailDomain);
  const org=p.organizer||{};
  out={ source:'Cal.com', email, firstName:nameParts[0]||'', lastName:nameParts.slice(1).join(' '), fullName:String(a.name||'').trim(), domain,
    startTime:p.startTime||'', title:p.title||p.eventTypeTitle||'', meetingUrl:(p.videoCallData&&p.videoCallData.url)||p.location||'', bookingUid:p.uid||'',
    notes:(p.responses&&p.responses.notes&&p.responses.notes.value)||p.additionalNotes||'',
    hostKeys:[org.email, org.username, org.name, p.eventTypeTitle, p.type].map(x=>String(x||'').toLowerCase().trim()).filter(Boolean), clientRecId:'' };
} else if(manual){
  const b=manual.body||{};
  const email=String(b.email||'').toLowerCase().trim();
  const emailDomain=email.split('@')[1]||'';
  out={ source:String(b.source||'manual'), email, firstName:String(b.firstName||''), lastName:String(b.lastName||''), fullName:String(b.fullName||((b.firstName||'')+' '+(b.lastName||''))).trim(), domain:stripDomain(b.domain)||(FREEMAIL.has(emailDomain)?'':emailDomain),
    startTime:String(b.startTime||''), title:String(b.title||''), meetingUrl:String(b.meetingUrl||''), bookingUid:String(b.bookingUid||''), notes:String(b.notes||''),
    hostKeys:(Array.isArray(b.hostKeys)?b.hostKeys:[]).map(x=>String(x||'').toLowerCase().trim()).filter(Boolean), clientRecId:String(b.clientRecId||'') };
} else { return [{ json:{ _ignore:true, reason:'no trigger payload' } }]; }
if(!out.email) return [{ json:{ _ignore:true, reason:'booking without an attendee email' } }];
out._ignore=false;
return [{ json: out }];

// Which client does this booking belong to? Nothing hardcoded: the registry decides.
// 1. The manual door may name the client outright.
// 2. The booking's host keys (organizer email / username / event title) against each client's Booking Keys lines.
// 3. The attendee's domain against each client's own Email Domains: that is a client meeting, not a lead.
const n=$('Normalize Booking').first().json;
const clients=$input.all().map(it=>it.json).filter(r=>r&&r.id).map(r=>{ const f=r.fields||r; return { id:r.id, f }; });
const lines=(v)=>String(v||'').split('\n').map(s=>s.toLowerCase().trim()).filter(Boolean);
const pick=(c)=>{ const f=c.f; const name=String(f['Client']||''); return { clientRecId:c.id, clientName:name, clientSlug:name.toLowerCase().replace(/[^a-z0-9]/g,''), slackChannel:String(f['Slack Channel ID']||'').trim(), pvWorkspace:String(f['PlusVibe Workspace ID']||'').trim(), dashboardPage:String(f['Dashboard Page ID']||'').trim(), isFlowroots:name.toLowerCase()==='flowroots' }; };
let hit=null, resolution='';
if(n.clientRecId){ hit=clients.find(c=>c.id===n.clientRecId)||null; resolution=hit?'named by the caller':''; }
if(!hit && n.hostKeys && n.hostKeys.length){
  hit=clients.find(c=>lines(c.f['Booking Keys']).some(k=>n.hostKeys.includes(k)))||null;
  if(hit) resolution='host key matched Booking Keys';
}
let clientMeeting=false;
if(!hit && n.domain){
  const own=clients.find(c=>lines(c.f['Email Domains']).includes(n.domain))||null;
  if(own){ hit=own; clientMeeting=true; resolution='attendee domain is the client\'s own domain'; }
}
if(!hit) return [{ json:{ clientRecId:'', clientName:'', clientMeeting:false, resolution:'no client matched host keys '+JSON.stringify(n.hostKeys||[]) } }];
return [{ json: Object.assign(pick(hit), { clientMeeting, resolution }) }];

// Not in the CRM: is this a lead we generated? The client's sequencer says.
const c=$('Resolve Client').first().json;
const r=$input.first().json||{};
const body=(r.body!==undefined)?r.body:r;
let lead=null;
if(body&&typeof body==='object'){ if(body._id||body.email) lead=body; else if(Array.isArray(body.leads)&&body.leads.length) lead=body.leads[0]; else if(body.lead&&typeof body.lead==='object') lead=body.lead; }
if(!c.pvWorkspace) return [{ json:{ ours:false, why:'client has no PlusVibe workspace to check', campaign:'', companyName:'', title:'' } }];
if(!lead) return [{ json:{ ours:false, why:'not a lead in the client\'s PlusVibe workspace', campaign:'', companyName:'', title:'', raw:JSON.stringify(body).slice(0,300) } }];
const campaign=String(lead.campaign_name||lead.campaign||'').trim();
return [{ json:{ ours:true, why:'found in PlusVibe'+(campaign?' (campaign '+campaign+')':''), campaign, companyName:String(lead.company_name||'').trim(), title:String(lead.job_title||'').trim(), pvLeadId:String(lead._id||'') } }];

let prospectId='', priorNotes='', existed=false;
try{ const f=$('Find Prospect').first().json; if(f&&f.id){ prospectId=f.id; const ff=f.fields||f; priorNotes=ff.contextNotes||''; existed=true; } }catch(e){}
if(!prospectId){ try{ prospectId=$('Create Prospect').first().json.id||''; }catch(e){} }
let ours='', why='';
try{ const a=$('Assess Lead').first().json; ours=a.ours; why=a.why||''; }catch(e){}
return [{ json:{ prospectId, priorNotes, existed, createdFromSequencer:!existed&&!!prospectId, why } }];

const n=$('Normalize Booking').first().json;
const c=$('Resolve Client').first().json;
const p=$('Resolve Prospect').first().json;
if(!c.slackChannel) return [{ json:{ post:false, channel:'', text:'' } }];
const when=n.startTime?new Date(n.startTime).toUTCString():'(time unknown)';
let url='';
if(p.prospectId&&c.dashboardPage){ try{ url='https://airtable.com/appQG6dK0FIOhTxOl/'+c.dashboardPage+'?detail='+Buffer.from(JSON.stringify({pageId:'pagU8C93nMn6vPMTM',rowId:p.prospectId}),'utf8').toString('base64').replace(/=+$/,''); }catch(e){} }
const text=[':calendar: *Call booked* ('+n.source+')',
  '*Who:* '+(n.fullName||n.email)+' <'+n.email+'>'+(n.domain?' · '+n.domain:''),
  '*When:* '+when, n.title?'*What:* '+n.title:'', n.meetingUrl?'*Link:* '+n.meetingUrl:'',
  '*CRM:* '+(p.existed?'existing prospect, marked Scheduled Call':'prospect created from the sequencer lead ('+p.why+'), marked Scheduled Call')+(url?' · <'+url+'|open in pipeline>':'')
].filter(Boolean).join('\n');
return [{ json:{ post:true, channel:c.slackChannel, text } }];

const sd=$getWorkflowStaticData('global'); const rs=sd.runStartedAt||0;
let n={}; try{ n=$('Normalize Booking').first().json||{}; }catch(e){}
let c={}; try{ c=$('Resolve Client').first().json||{}; }catch(e){}
let p=null; try{ p=$('Resolve Prospect').first().json; }catch(e){}
let a=null; try{ a=$('Assess Lead').first().json; }catch(e){}
let meetingId=''; try{ meetingId=$('Create Meeting').first().json.id||''; }catch(e){}
if(!meetingId){ try{ meetingId=$('Create Unattributed Meeting').first().json.id||''; }catch(e){} }
let stamped=false; try{ stamped=!!($('Stamp Booked').first().json||{}).id; }catch(e){}
let posted=false; try{ const s=$('Post Booking Card').first().json||{}; posted=!!(s.ts||(s.message&&s.message.ts)||s.ok===true); }catch(e){}
const failed=[]; const skipped=[];
const who=(n.fullName||'')+' <'+(n.email||'')+'>'+(n.domain?' ('+n.domain+')':'');
const lines=['- **Source:** '+(n.source||'?')+(n.bookingUid?' ('+n.bookingUid+')':''), '- **Attendee:** '+who, '- **When:** '+(n.startTime||'?')+(n.title?' · '+n.title:'')];
let head='';
if(n._ignore){ head='Ignored'; skipped.push(n.reason||'not a booking'); }
else if(!c.clientRecId){ head='Unresolved client'; skipped.push(c.resolution||'no client matched'); }
else if(c.clientMeeting){ head='Client meeting, not a lead'; skipped.push(c.resolution); lines.push('- **Client:** '+c.clientName); }
else {
  lines.push('- **Client:** '+c.clientName+' ('+(c.resolution||'')+')');
  if(p&&p.prospectId){ head=(p.existed?'Inbox lead booked':'Sequencer lead booked (was not in the inbox)'); lines.push('- **Prospect:** '+(p.existed?'matched existing row':'created from the sequencer lead, '+(p.why||''))+' ('+p.prospectId+')'); lines.push('- **Stamped:** '+(stamped?'OutreachStatus = Scheduled Call, Call Booked At = today'+(c.isFlowroots?', PipelineStatus = Scheduled Call':''):'NOT stamped')); if(!stamped) failed.push('prospect not stamped'); }
  else if(a&&!a.ours){ head='Booking not attributed'; skipped.push(a.why||'not ours'); }
  else { head='Booking'; failed.push('prospect neither found nor created'); }
  lines.push('- **Meeting:** '+(meetingId?'Meetings row created ('+meetingId+')':'NOT created')); if(!meetingId) failed.push('meeting row not created');
  if(c.slackChannel&&p&&p.prospectId){ lines.push('- **Slack:** '+(posted?'card posted to '+c.slackChannel:'card NOT posted')); if(!posted) failed.push('slack card not posted'); }
}
let desc='**'+head+': '+(n.fullName||n.email||'?')+'**\n\n'+lines.join('\n');
if(skipped.length) desc+='\n\n**Skipped ('+skipped.length+')**\n'+skipped.map(x=>'- '+x).join('\n');
if(failed.length) desc+='\n\n**FAILED ('+failed.length+')**\n'+failed.map(x=>'- '+x).join('\n');
const row={ 'Automation':'Handle New Booking', 'Status':failed.length?'Succeeded with errors':'Succeeded', 'Run at':$now.toISO(), 'Records In':1, 'Records Out':(p&&p.prospectId?1:0)+(meetingId?1:0), 'Errors':failed.length, 'Target':n.email||'', 'Trigger':'event', 'Execution ID':String($execution.id), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id, 'Duration s':Math.round(($now.toMillis()-(rs||$now.toMillis()))/1000), 'Description':desc };
if(c.clientRecId) row['Client']=[c.clientRecId];
return [{ json: row }];
